(function () {
'use strict';
const currentYearEl = document.getElementById('current-year');
if (currentYearEl) {
currentYearEl.textContent = new Date().getFullYear();
}
const themeToggleBtn = document.getElementById('theme-toggle');
const rootHtml = document.documentElement;
const THEME_STORAGE_KEY = 'yy_portfolio_theme';
function getInitialTheme() {
const savedTheme = localStorage.getItem(THEME_STORAGE_KEY);
if (savedTheme === 'light' || savedTheme === 'dark') {
return savedTheme;
}
if (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches) {
return 'light';
}
return 'dark';
}
function applyTheme(theme) {
rootHtml.setAttribute('data-theme', theme);
localStorage.setItem(THEME_STORAGE_KEY, theme);
if (themeToggleBtn) {
themeToggleBtn.setAttribute(
'aria-label',
theme === 'dark' ? 'Switch to light theme' : 'Switch to dark theme'
);
themeToggleBtn.setAttribute(
'title',
theme === 'dark' ? 'Switch to light theme' : 'Switch to dark theme'
);
}
}
const initialTheme = getInitialTheme();
applyTheme(initialTheme);
if (themeToggleBtn) {
themeToggleBtn.addEventListener('click', function () {
const currentTheme = rootHtml.getAttribute('data-theme') || 'dark';
const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
applyTheme(newTheme);
});
}
if (window.matchMedia) {
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function (e) {
if (!localStorage.getItem(THEME_STORAGE_KEY)) {
applyTheme(e.matches ? 'dark' : 'light');
}
});
}
const mobileToggleBtn = document.getElementById('mobile-toggle');
const primaryNav = document.getElementById('primary-nav');
const navLinks = document.querySelectorAll('.nav-link');
function openMobileMenu() {
if (!mobileToggleBtn || !primaryNav) return;
mobileToggleBtn.classList.add('is-active');
mobileToggleBtn.setAttribute('aria-expanded', 'true');
mobileToggleBtn.setAttribute('aria-label', 'Close navigation menu');
primaryNav.classList.add('is-open');
document.body.style.overflow = 'hidden';
}
function closeMobileMenu() {
if (!mobileToggleBtn || !primaryNav) return;
mobileToggleBtn.classList.remove('is-active');
mobileToggleBtn.setAttribute('aria-expanded', 'false');
mobileToggleBtn.setAttribute('aria-label', 'Open navigation menu');
primaryNav.classList.remove('is-open');
document.body.style.overflow = '';
}
if (mobileToggleBtn && primaryNav) {
mobileToggleBtn.addEventListener('click', function () {
const isOpen = primaryNav.classList.contains('is-open');
if (isOpen) {
closeMobileMenu();
} else {
openMobileMenu();
}
});
navLinks.forEach(function (link) {
link.addEventListener('click', function () {
closeMobileMenu();
});
});
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape' && primaryNav.classList.contains('is-open')) {
closeMobileMenu();
mobileToggleBtn.focus();
}
});
document.addEventListener('click', function (e) {
if (
primaryNav.classList.contains('is-open') &&
!primaryNav.contains(e.target) &&
!mobileToggleBtn.contains(e.target)
) {
closeMobileMenu();
}
});
}
const trackedSections = document.querySelectorAll('section[id], header[id]');
const backToTopBtn = document.getElementById('back-to-top');
let isScrollTicking = false;
function updateScrollUI() {
const scrollY = window.scrollY;
if (backToTopBtn) {
if (scrollY > 350) {
backToTopBtn.classList.add('visible');
} else {
backToTopBtn.classList.remove('visible');
}
}
const scrollPosition = scrollY + 120;
let currentSectionId = '';
for (let i = 0; i < trackedSections.length; i++) {
const section = trackedSections[i];
const sectionTop = section.offsetTop;
const sectionHeight = section.offsetHeight;
if (scrollPosition >= sectionTop && scrollPosition < sectionTop + sectionHeight) {
currentSectionId = section.getAttribute('id');
}
}
if (currentSectionId) {
for (let j = 0; j < navLinks.length; j++) {
const link = navLinks[j];
if (link.getAttribute('href') === '#' + currentSectionId) {
link.classList.add('active');
} else {
link.classList.remove('active');
}
}
}
}
function onScroll() {
if (!isScrollTicking) {
window.requestAnimationFrame(function () {
updateScrollUI();
isScrollTicking = false;
});
isScrollTicking = true;
}
}
window.addEventListener('scroll', onScroll, { passive: true });
updateScrollUI();
const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (!prefersReducedMotion && 'IntersectionObserver' in window) {
const animatableElements = document.querySelectorAll(
'.about-grid, .summary-card, .skill-category-card, .area-card, .project-card, .certification-card, .timeline-item, .education-card, .objective-card, .contact-grid'
);
animatableElements.forEach(function (el) {
el.classList.add('reveal');
});
const revealObserver = new IntersectionObserver(
function (entries, observer) {
entries.forEach(function (entry) {
if (entry.isIntersecting) {
entry.target.classList.add('is-visible');
observer.unobserve(entry.target);
}
});
},
{
root: null,
threshold: 0.1,
rootMargin: '0px 0px -40px 0px',
}
);
animatableElements.forEach(function (el) {
revealObserver.observe(el);
});
}
if (backToTopBtn) {
backToTopBtn.addEventListener('click', function () {
window.scrollTo({
top: 0,
behavior: 'smooth',
});
const brandLogo = document.querySelector('.brand-logo');
if (brandLogo) brandLogo.focus();
});
}
const modalTriggers = document.querySelectorAll('[data-modal]');
const allModals = document.querySelectorAll('.modal-overlay');
let lastActiveElement = null;
function openModal(modalId) {
const targetModal = document.getElementById(modalId);
if (!targetModal) return;
lastActiveElement = document.activeElement;
targetModal.removeAttribute('hidden');
document.body.style.overflow = 'hidden';
const closeBtn = targetModal.querySelector('.modal-close-btn');
if (closeBtn) {
closeBtn.focus();
}
}
function closeModal(modal) {
if (!modal) return;
modal.setAttribute('hidden', '');
document.body.style.overflow = '';
if (lastActiveElement && typeof lastActiveElement.focus === 'function') {
lastActiveElement.focus();
}
}
modalTriggers.forEach(function (trigger) {
trigger.addEventListener('click', function () {
const modalId = trigger.getAttribute('data-modal');
openModal(modalId);
});
trigger.addEventListener('keydown', function (e) {
if (e.key === 'Enter' || e.key === ' ') {
e.preventDefault();
const modalId = trigger.getAttribute('data-modal');
openModal(modalId);
}
});
});
allModals.forEach(function (modal) {
const closeButtons = modal.querySelectorAll('[data-close-modal]');
closeButtons.forEach(function (btn) {
btn.addEventListener('click', function () {
closeModal(modal);
});
});
modal.addEventListener('keydown', function (e) {
if (e.key === 'Escape') {
closeModal(modal);
}
});
});
const copyEmailBtn = document.getElementById('copy-email-btn');
const EMAIL_ADDRESS = 'youssefyahia147258@gmail.com';
if (copyEmailBtn) {
copyEmailBtn.addEventListener('click', function () {
const copyTextSpan = copyEmailBtn.querySelector('.copy-text');
if (navigator.clipboard && navigator.clipboard.writeText) {
navigator.clipboard
.writeText(EMAIL_ADDRESS)
.then(function () {
handleCopySuccess(copyTextSpan);
})
.catch(function () {
fallbackCopy(EMAIL_ADDRESS, copyTextSpan);
});
} else {
fallbackCopy(EMAIL_ADDRESS, copyTextSpan);
}
});
}
function handleCopySuccess(textSpan) {
copyEmailBtn.classList.add('copied');
if (textSpan) textSpan.textContent = 'Copied!';
setTimeout(function () {
copyEmailBtn.classList.remove('copied');
if (textSpan) textSpan.textContent = 'Copy';
}, 2500);
}
function fallbackCopy(text, textSpan) {
const tempInput = document.createElement('textarea');
tempInput.value = text;
tempInput.style.position = 'fixed';
tempInput.style.opacity = '0';
document.body.appendChild(tempInput);
tempInput.select();
try {
document.execCommand('copy');
handleCopySuccess(textSpan);
} catch (err) {
alert('Email address: ' + text);
} finally {
document.body.removeChild(tempInput);
}
}
const copyCertBtn = document.getElementById('copy-cert-code');
const CERT_CODE = 'ICT20261024015953';
if (copyCertBtn) {
copyCertBtn.addEventListener('click', function () {
const copyTextSpan = copyCertBtn.querySelector('.copy-code-text');
if (navigator.clipboard && navigator.clipboard.writeText) {
navigator.clipboard
.writeText(CERT_CODE)
.then(function () {
handleCertCopySuccess(copyCertBtn, copyTextSpan);
})
.catch(function () {
fallbackCertCopy(CERT_CODE, copyCertBtn, copyTextSpan);
});
} else {
fallbackCertCopy(CERT_CODE, copyCertBtn, copyTextSpan);
}
});
}
function handleCertCopySuccess(btn, textSpan) {
btn.classList.add('copied');
if (textSpan) textSpan.textContent = 'Copied!';
setTimeout(function () {
btn.classList.remove('copied');
if (textSpan) textSpan.textContent = 'Copy';
}, 2500);
}
function fallbackCertCopy(text, btn, textSpan) {
const tempInput = document.createElement('textarea');
tempInput.value = text;
tempInput.style.position = 'fixed';
tempInput.style.opacity = '0';
document.body.appendChild(tempInput);
tempInput.select();
try {
document.execCommand('copy');
handleCertCopySuccess(btn, textSpan);
} catch (err) {
prompt('Certificate Code:', text);
} finally {
document.body.removeChild(tempInput);
}
}
const contactForm = document.getElementById('contact-form');
const nameInput = document.getElementById('form-name');
const emailInput = document.getElementById('form-email');
const subjectInput = document.getElementById('form-subject');
const messageInput = document.getElementById('form-message');
const charCounter = document.getElementById('char-counter');
const formStatus = document.getElementById('form-status');
const composeMailBtn = document.getElementById('compose-mail-btn');
if (messageInput && charCounter) {
messageInput.addEventListener('input', function () {
const len = messageInput.value.length;
charCounter.textContent = len + ' / 500';
if (len >= 480) {
charCounter.style.color = 'var(--status-amber)';
} else {
charCounter.style.color = 'var(--text-muted)';
}
});
}
function setFieldError(field, errorId, message) {
field.classList.add('input-error');
const errorEl = document.getElementById(errorId);
if (errorEl) {
errorEl.textContent = message;
}
}
function clearFieldError(field, errorId) {
field.classList.remove('input-error');
const errorEl = document.getElementById(errorId);
if (errorEl) {
errorEl.textContent = '';
}
}
function validateEmail(email) {
const re = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
return re.test(String(email).trim());
}
if (nameInput) {
nameInput.addEventListener('input', function () {
if (nameInput.value.trim().length >= 2) {
clearFieldError(nameInput, 'name-error');
}
});
}
if (emailInput) {
emailInput.addEventListener('input', function () {
if (validateEmail(emailInput.value)) {
clearFieldError(emailInput, 'email-error');
}
});
}
if (subjectInput) {
subjectInput.addEventListener('change', function () {
if (subjectInput.value) {
clearFieldError(subjectInput, 'subject-error');
}
});
}
if (messageInput) {
messageInput.addEventListener('input', function () {
if (messageInput.value.trim().length >= 10) {
clearFieldError(messageInput, 'message-error');
}
});
}
if (contactForm) {
contactForm.addEventListener('submit', function (e) {
e.preventDefault();
let isValid = true;
let firstInvalidField = null;
const nameVal = nameInput ? nameInput.value.trim() : '';
if (!nameVal) {
setFieldError(nameInput, 'name-error', 'Please enter your name.');
isValid = false;
if (!firstInvalidField) firstInvalidField = nameInput;
} else if (nameVal.length < 2) {
setFieldError(nameInput, 'name-error', 'Name must be at least 2 characters.');
isValid = false;
if (!firstInvalidField) firstInvalidField = nameInput;
} else {
clearFieldError(nameInput, 'name-error');
}
const emailVal = emailInput ? emailInput.value.trim() : '';
if (!emailVal) {
setFieldError(emailInput, 'email-error', 'Please enter your email address.');
isValid = false;
if (!firstInvalidField) firstInvalidField = emailInput;
} else if (!validateEmail(emailVal)) {
setFieldError(emailInput, 'email-error', 'Please enter a valid email address (e.g. name@domain.com).');
isValid = false;
if (!firstInvalidField) firstInvalidField = emailInput;
} else {
clearFieldError(emailInput, 'email-error');
}
const subjectVal = subjectInput ? subjectInput.value : '';
if (!subjectVal) {
setFieldError(subjectInput, 'subject-error', 'Please select an inquiry topic.');
isValid = false;
if (!firstInvalidField) firstInvalidField = subjectInput;
} else {
clearFieldError(subjectInput, 'subject-error');
}
const messageVal = messageInput ? messageInput.value.trim() : '';
if (!messageVal) {
setFieldError(messageInput, 'message-error', 'Please write your message.');
isValid = false;
if (!firstInvalidField) firstInvalidField = messageInput;
} else if (messageVal.length < 10) {
setFieldError(messageInput, 'message-error', 'Message must be at least 10 characters long.');
isValid = false;
if (!firstInvalidField) firstInvalidField = messageInput;
} else {
clearFieldError(messageInput, 'message-error');
}
if (!isValid) {
if (formStatus) {
formStatus.className = 'form-status status-error';
formStatus.textContent = 'Please correct the highlighted fields above.';
}
if (firstInvalidField) {
firstInvalidField.focus();
}
return;
}
const submitBtn = document.getElementById('submit-btn');
const originalBtnHtml = submitBtn ? submitBtn.innerHTML : '';
if (submitBtn) {
submitBtn.disabled = true;
submitBtn.innerHTML = '<span>Validating...</span>';
}
setTimeout(function () {
if (formStatus) {
formStatus.className = 'form-status status-success';
formStatus.innerHTML =
'<strong>Validation successful!</strong><br>' +
'Thank you, ' +
escapeHtml(nameVal) +
'. In this client-side demonstration, your form inputs passed all validation checks. ' +
'To deliver this message to Youssef directly, please send an email to <a href="mailto:' +
EMAIL_ADDRESS +
'" style="text-decoration: underline; color: inherit; font-weight: bold;">' +
EMAIL_ADDRESS +
'</a> or connect on LinkedIn.';
}
if (submitBtn) {
submitBtn.disabled = false;
submitBtn.innerHTML = originalBtnHtml;
}
contactForm.reset();
if (charCounter) {
charCounter.textContent = '0 / 500';
}
}, 700);
});
}
function escapeHtml(str) {
return str
.replace(/&/g, '&amp;')
.replace(/</g, '&lt;')
.replace(/>/g, '&gt;')
.replace(/"/g, '&quot;')
.replace(/'/g, '&#039;');
}
if (composeMailBtn) {
composeMailBtn.addEventListener('click', function () {
const nameVal = nameInput ? nameInput.value.trim() : '';
const emailVal = emailInput ? emailInput.value.trim() : '';
const subjectVal = subjectInput && subjectInput.value ? subjectInput.value : 'Junior AI/ML Inquiry';
const messageVal = messageInput ? messageInput.value.trim() : '';
let body = '';
if (messageVal) {
body += messageVal + '\n\n';
}
if (nameVal) {
body += 'From: ' + nameVal + '\n';
}
if (emailVal) {
body += 'Reply-to: ' + emailVal + '\n';
}
const mailtoUrl =
'mailto:' +
EMAIL_ADDRESS +
'?subject=' +
encodeURIComponent(subjectVal) +
'&body=' +
encodeURIComponent(body);
window.location.href = mailtoUrl;
});
}
})();